={{ (() => {
  const detect = (s) => {
    const t = String(s || '').toLowerCase();
    if (/pick ?-?up|camioneta|chata/.test(t)) return 'pickup';
    if (/\bsuvs?\b|todo ?terreno/.test(t)) return 'suv';
    if (/sed[aá]n/.test(t)) return 'sedan';
    if (/hatch/.test(t)) return 'hatchback';
    if (/utilitari|furg[oó]n/.test(t)) return 'utilitario';
    return '';
  };
  const lead = $('Leer lead (estado)').item.json;
  return detect($('Webhook Render').item.json.body.content)
      || detect(lead.lead_vehiculo)
      || String(lead.carroceria_pedida_hist || '');
})() }}

={{ (() => {
  const t = String($('Webhook Render').item.json.body.content || '').toLowerCase();
  const G = /\b(grandes?|amplio|espacios[oa]s?)\b/;
  const M = /\b(median[oa]s?)\b/;
  const C = /\b(chic[oa]s?|peque[nñ][oa]s?|compact[oa]s?)\b/;
  const neg = /\b(no|nada|ni|tampoco)\b[^.,;!?]{0,20}$/;
  const pide = (re) => { const m = t.match(re); return !!m && !neg.test(t.slice(0, m.index)); };
  const r = pide(G) ? 'grande' : pide(M) ? 'mediano' : pide(C) ? 'chico' : '';
  return r.replace(/[^a-z]/g, '');
})() }}

