// C2: el agente devuelve ids; los datos salen de Postgres.
// Todo el bloque va en try/catch: si algo acá tira, el usuario tiene que recibir
// una burbuja igual (mismo blindaje que tenía Responder a Render).
const cfg = $('Config').first().json;

function fallback(motivo) {
  const msgs = [{ type: 'text', content: 'Uy, se me trabó el sistema un segundo. Me repetís lo último?' }];
  return [{ json: {
    respuesta: { session_id: cfg.session_id, messages: msgs, images: [], product_cards: [], error: null },
    historial: { messages: msgs, images: [], product_cards: [] },
    debug_motivo: motivo,
  } }];
}

try {
  const crudo = $('Franco (AI Agent)').first().json.output;
  const output = (crudo && typeof crudo === 'object' && !Array.isArray(crudo)) ? crudo : {};

  // Filas hidratadas. alwaysOutputData deja un item vacío cuando no hubo ids.
  const filas = $('Hidratar autos').all()
    .map(i => i.json)
    .filter(r => r && r.id != null);

  // El orden lo manda Franco (es el orden en que los nombra en el texto).
  // = ANY no preserva orden, así que reordenamos por auto_ids.
  const ids = Array.isArray(output.auto_ids)
    ? output.auto_ids.map(n => parseInt(n, 10)).filter(n => Number.isInteger(n))
    : [];
  const porId = new Map(filas.map(r => [Number(r.id), r]));

  // Autos cuyas FOTOS ya se mandaron en los últimos 8 mensajes de esta sesión. Viene como
  // "2,5,14" desde "Autos ya mostrados"; si no hay nada, viene ''. Sólo mira `images`
  // previas: haber aparecido como card NO cuenta, porque ver la ficha con fotos después de
  // la miniatura es un flujo válido.
  let yaMostrados = new Set();
  try {
    const crudoIds = String($('Autos ya mostrados').first().json.ids_recientes || '');
    yaMostrados = new Set(crudoIds.split(',').map(s => parseInt(s, 10)).filter(n => Number.isInteger(n)));
  } catch (e) {
    // Si el nodo no devolvió nada, no filtramos: preferimos repetir una foto antes que
    // dejar al cliente sin ver el auto.
  }
  // Autos cuyas CARDS (product_cards) ya se mandaron en los últimos 8 mensajes. Pedido de
  // Agustina: no repetir el mismo mazo cuando el cliente sigue hablando de esos autos.
  let cardsMostradas = new Set();
  try {
    const crudoCards = String($('Autos ya mostrados').first().json.cards_recientes || '');
    cardsMostradas = new Set(crudoCards.split(',').map(s => parseInt(s, 10)).filter(n => Number.isInteger(n)));
  } catch (e) {}
  const autos = [...new Set(ids)].map(id => porId.get(id)).filter(Boolean);

  // CENTINELA DE CERO FILAS (v102). Si "Listar stock" corrió en ESTE turno y devolvió el
  // centinela —una respuesta sin ninguna fila con id—, entonces no hay stock que mostrar y este
  // turno no lleva material gráfico. Hace falta porque Franco puede devolver auto_ids DE MEMORIA
  // aunque la herramienta no le haya dado nada: en la ejecución 12601 el gate de v85 bloqueó bien
  // (0 filas) y aun así listó 6 autos, uno con un precio inventado.
  // Sólo aplica si la herramienta CORRIÓ: en los turnos que muestran un auto vía "Buscar auto" o
  // "Detalle auto", "Listar stock" no aparece en la ejecución y esto no se activa.
  // try/catch como todo el resto de este nodo: ante cualquier duda, el comportamiento de antes.
  let centinela = false;
  try {
    const _ls = $('Listar stock').first().json;
    const _filas = (_ls && Array.isArray(_ls.response)) ? _ls.response : null;
    if (_filas && _filas.length && _filas.every(r => !r || r.id == null)) {
      autos.length = 0;
      centinela = true;
    }
  } catch (e) {}

  let messages = Array.isArray(output.messages)
    ? output.messages.filter(m => m && typeof m.content === 'string' && m.content.trim())
    : [];
  if (messages.length === 0) {
    messages = [{ type: 'text', content: 'Uy, se me trabó el sistema un segundo. Me repetís lo último?' }];
  }
  // Las fotos cuelgan de la última burbuja de contenido, antes de que el guard
  // de cierre agregue la pregunta.
  // TB-3: encabezado del abanico de permuta por CÓDIGO (mata el eco de los datos del usado). Solo cuando
  // Listar stock corrió como capacidad/permuta (mira sus flags). Compone SOLO con lo que hay: nunca inventa
  // un usado, un anticipo ni un efectivo que el cliente no dio.
  try {
    if (autos.length >= 3) {
      // el tool Listar stock envuelve las filas en { response: [...] }; los flags están en la fila.
      let ls = {};
      try {
        const _raw = $('Listar stock').first().json;
        ls = (_raw && Array.isArray(_raw.response)) ? (_raw.response[0] || {}) : (_raw || {});
      } catch (e) {}
      let permuta = Number(ls.eco_permuta) === 1;
      let financia = Number(ls.eco_financia) === 1;
      let presu = Number(ls.eco_presu) === 1;
      // fallback si no se pudo leer del tool: usar el estado del CRM (nodo main-chain, siempre accesible).
      if (ls.eco_permuta == null) {
        try {
          const le = $('Leer lead (estado)').first().json;
          permuta = String(le.lead_entrega || '') === 'Sí' || (le.lead_usado && le.lead_usado !== 'No mencionado');
          // NORMALIZADO A PROPÓSITO (v110): la base guarda 'Sí' CON tilde —verificado: 495 filas
          // 'Sí', 68 'No', 1127 'No mencionado', cero 'Si'— y esta comparación pedía 'Si' sin
          // tilde, así que era SIEMPRE false. Y como la lectura del tool no funciona, este fallback
          // corre en todos los turnos: el encabezado decía "tu efectivo" a quien está financiando.
          // Se normaliza en vez de arreglar la tilde a secas porque el valor lo escribe un modelo.
          financia = /^s[ií]$/i.test(String(le.lead_financia || '').trim());
          presu = le.lead_presupuesto && le.lead_presupuesto !== 'No mencionado';
        } catch (e) {}
      }
      if (permuta || financia) {
        const partes = [];
        if (permuta) partes.push('tu usado como parte de pago');
        if (presu) partes.push(financia ? 'tu anticipo' : 'tu efectivo');
        if (financia) partes.push('la posibilidad de financiar');
        if (partes.length) {
          const unir = partes.length === 1 ? partes[0] : partes.slice(0, -1).join(', ') + ' y ' + partes[partes.length - 1];
          const encabezado = 'Con ' + unir + ', estas opciones te pueden servir:';
          // buscar la burbuja que tiene la lista de autos (viñetas)
          let ib = -1, li = -1;
          for (let k = 0; k < messages.length; k++) {
            const c = String(messages[k].content || '');
            const j = c.search(/(^|\n)\s*[-•]/);
            if (j >= 0) { ib = k; li = j; break; }
          }
          if (ib >= 0) {
            const c = String(messages[ib].content || '');
            if (li > 0) {
              // encabezado y lista en la misma burbuja: reemplazo el texto antes de la lista
              messages[ib] = Object.assign({}, messages[ib], { content: encabezado + c.slice(li) });
            } else if (ib > 0) {
              // la lista arranca sola en su burbuja: la burbuja anterior es el encabezado (donde vive el eco)
              messages[ib - 1] = Object.assign({}, messages[ib - 1], { content: encabezado });
            }
          }
        }
      }
    }
  } catch (e) {}
  const anchor = messages.length - 1;

  // fotos viene de jsonb; n8n suele darlo como array, pero si llega como string
  // lo parseamos en vez de romper.
  function fotosDe(fila) {
    let f = fila.fotos;
    if (typeof f === 'string') { try { f = JSON.parse(f); } catch (e) { f = null; } }
    const arr = Array.isArray(f) ? f : [];
    const limpias = arr.filter(u => typeof u === 'string' && u);
    return limpias.length ? limpias : (fila.foto_principal ? [fila.foto_principal] : []);
  }

  let images = [];
  let product_cards = [];
  if (autos.length >= 3) {
    // Dedup del mazo: si TODOS los autos de este turno ya se mandaron como card hace poco,
    // no se repite (el cliente sigue hablando de esos y ya los tiene en pantalla). Si hay al
    // menos uno nuevo, va la lista completa: filtrar auto por auto dejaría huecos en el catálogo.
    const hayNuevo = autos.some(a => !cardsMostradas.has(Number(a.id)));
    if (hayNuevo) {
      product_cards = autos.map(a => ({
        id: a.id, titulo: a.titulo, precio: a.precio, foto_principal: a.foto_principal,
      }));
    }
  } else if (autos.length >= 1) {
    // Acá sí: si las fotos de este auto ya se mandaron hace poco, no se reenvían.
    const sinRepetir = autos.filter(a => !yaMostrados.has(Number(a.id)));
    images = sinRepetir.flatMap(fotosDe).map(url => ({ url, after_message_index: anchor }));
  }

  // EL PRECIO LO PONE LA BASE, NO EL MODELO (v105). En cada RENGLÓN que nombra un auto del
  // catálogo y trae un monto, se compara con el precio real y se corrige si no coincide.
  // Medido: Franco escribió "Jeep Renegade 2019 — $24.500.000" (real $25.500.000), "Gol Trend
  // 2022 — $17.000.000" (real $9.200.000) y "EcoSport 2020 — $27.000.000" (real $19.800.000).
  // El prompt ya se lo prohíbe en cuatro lugares distintos desde v95 y sigue pasando, así que el
  // dato determinístico se arregla con código.
  // Acotado al MISMO RENGLÓN a propósito: un "$5.000.000 de anticipo" en otro párrafo no se toca.
  // try/catch como todo este nodo: ante cualquier duda, el texto sale como vino.
  try {
    const _cat = $('Leer lead (estado)').first().json.catalogo_precios || [];
    if (Array.isArray(_cat) && _cat.length) {
      const _fmt = (n) => '$' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
      const _esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      messages = messages.map(m => {
        let c = String((m && m.content) || '');
        for (const a of _cat) {
          if (!a || !a.t || !a.p) continue;
          const re = new RegExp('([^\\n]*\\b' + _esc(a.t) + '\\b[^\\n]*?)\\$\\s?([0-9][0-9.]{6,})', 'gi');
          c = c.replace(re, (todo, previo, monto) => {
            const n = parseInt(String(monto).replace(/\./g, ''), 10);
            if (!Number.isFinite(n) || n === Number(a.p)) return todo;
            // v127 · NO TODO MONTO EN EL RENGLÓN ES EL PRECIO DEL AUTO. El corrector pisaba el
            // anticipo mínimo: en la ejecución 15225 el modelo escribió "el anticipo mínimo que
            // necesitas es $10.500.000" y al cliente le llegó "$21.000.000". Los dos guards sólo
            // pueden DEJAR de corregir, nunca corregir de más.
            // (1) SEMÁNTICA: lo que viene justo antes dice que ese monto no es el precio.
            if (/(anticipo|entrega|se[ñn]a|cuota|m[íi]nimo|financi\w*|aportar|poner)[^$]{0,40}$/i.test(previo)) return todo;
            // (2) ARITMÉTICA: la mitad exacta del precio ES el anticipo mínimo, por definición.
            if (n === Math.floor(Number(a.p) / 2)) return todo;
            return previo + _fmt(a.p);
          });
        }
        return Object.assign({}, m, { content: c });
      });
    }
  } catch (e) {}

  // EL AÑO TAMBIÉN LO PONE LA BASE (v109). Hermano del corrector de precios de v105, con la MISMA
  // fuente (`catalogo_precios` de `Leer lead (estado)`, main chain) — el único mecanismo de este
  // nodo verificado disparando en producción (ejecución 13583: corrigió cuatro precios).
  // MEDIDO HOY: "Volkswagen Gol Trend 2022" (es 2018), "Renault Duster 2018" (es 2023),
  // "Jeep Renegade 2019" (es 2021), "Toyota Etios 2018" (es 2019).
  // Acotado a los 12 caracteres que siguen al nombre del auto, y sin dígitos en el medio, para no
  // pisar un número más adelante del renglón (los km, el precio).
  try {
    const _le0 = $('Leer lead (estado)').first().json;
    const _cat = _le0.catalogo_precios || [];
    if (Array.isArray(_cat) && _cat.length) {
      const _esc = (s) => String(s).replace(/[.*+?^\${}()|[\]\\]/g, '\\$&');
      // EL AÑO DEL AUTO DEL CLIENTE NO SE PISA (v116). Si el cliente entrega un modelo que TAMBIÉN
      // está en stock, este corrector le imponía a SU auto el año que ese modelo tiene en el stock.
      // PRUEBA VINCULANTE, los dos nodos de la ejecución 14244: el modelo escribió "tu Toyota Hilux
      // 2014" y al cliente le llegó "tu Toyota Hilux 2021". El CRM había guardado bien
      // ("Toyota Hilux 2014 - 135.000 km"): lo rompió este bloque.
      // Dos guardas en OR, y las dos sólo pueden DEJAR DE CORREGIR, nunca corregir de más:
      //   (1) el año es uno de los que trae lead_usado;
      //   (2) el nombre viene con un posesivo delante ("tu Toyota Hilux") — ésta NO depende del CRM
      //       y por eso cubre el turno en que el CRM todavía no escribió, que es el retraso que ya
      //       nos costó v115.
      // EL SESGO ES DELIBERADO: pasarse de prudente deja vivo un año inventado (bug de v109, que el
      // eval caza); quedarse corto le cambia el auto al cliente en la cara. No son comparables.
      const _aniosUsado = new Set(String(_le0.lead_usado || '').match(/\b(?:19|20)\d{2}\b/g) || []);
      messages = messages.map(m => {
        let c = String((m && m.content) || '');
        for (const a of _cat) {
          if (!a || !a.t || !a.a) continue;
          const re = new RegExp('([^\\n]*\\b' + _esc(a.t) + '\\b[^0-9\\n]{0,12})\\b((?:19|20)\\d{2})\\b', 'gi');
          const _rePos = new RegExp('\\b(?:tu|su|mi|tus|sus|mis)\\s+' + _esc(a.t) + '\\b', 'i');
          c = c.replace(re, (todo, previo, anio) => {
            if (_aniosUsado.has(anio)) return todo;
            if (_rePos.test(todo)) return todo;
            return previo + String(a.a);
          });
        }
        return Object.assign({}, m, { content: c });
      });
    }
  } catch (e) {}

  // EL RENGLÓN QUE OFRECE UN AUTO QUE NO EXISTE SE BORRA (v109). Distinto del precio de v105: ahí
  // el auto existe y hay con qué corregir; acá no existe y no hay número que poner.
  // MEDIDO HOY: "Chevrolet Cruze 2019 — $22.500.000", "Renault Sandero 2020/2021/2022",
  // "Nissan Kicks 2019", "Volkswagen Tiguan 2018", "Nissan Versa 2022".
  // UNA OFERTA SON LAS TRES COSAS JUNTAS: renglón de lista + precio + año. Con las tres, un
  // "- Sellos, $208.000" (sin año) y un "el Etios que viste" (sin viñeta) quedan afuera solos.
  // El usado del PROPIO cliente se respeta: es su auto, no una invención.
  try {
    const _le = $('Leer lead (estado)').first().json;
    const _cat = _le.catalogo_precios || [];
    if (Array.isArray(_cat) && _cat.length) {
      const _nombres = [];
      for (const a of _cat) {
        if (!a || !a.t) continue;
        _nombres.push(String(a.t).toLowerCase());
        // "Volkswagen Gol Trend" -> "gol trend". El modelo suelto sólo cuenta si tiene letras:
        // "208" a secas matchearía adentro de cualquier monto, así que ese va sólo con la marca.
        const _mod = String(a.t).split(' ').slice(1).join(' ');
        if (/[a-z]/i.test(_mod)) _nombres.push(_mod.toLowerCase());
      }
      const _usado = String(_le.lead_usado || '').toLowerCase();
      // EL ENCABEZADO PEGADO AL ÍTEM TAMBIÉN ES UN RENGLÓN DE OFERTA (v114). MEDIDO, no supuesto:
      // "Alto: - Volkswagen Polo 2021 — 25.000 km — $15.000.000 (hatchback)" salió a producción
      // (mensajes_demo 11684) y NO HAY NINGÚN POLO EN EL STOCK. El borrado de acá abajo no lo veía
      // porque exigía la viñeta al PRINCIPIO del renglón, y el check `no_inventa_autos` del eval
      // tenía EL MISMO hueco: ese formato pasaba por los dos lados. Se arregla en los dos a la vez.
      // El patrón es el MISMO TEXTO que `ES_ITEM` en evals/run.mjs y hay un assert que lo fija:
      // si divergen, el formato vuelve a pasar entero por algún lado.
      const _ITEM = /^\s*(?:[^\n:]{1,25}:\s*)?(?:[-•*]|\d+[.)])\s+\S/;
      const _esOferta = (l) =>
        _ITEM.test(l) &&
        /\$\s?\d{1,3}(?:\.\d{3})+/.test(l) &&
        /\b(?:19|20)\d{2}\b/.test(l);
      const _esEncabezado = (l) => /^\s*[^\n:]{1,25}:\s*$/.test(l);
      const _esItem = (l) => _ITEM.test(l);
      const nuevos = messages.map(m => {
        const c = String((m && m.content) || '');
        if (!c) return m;
        const lineas = c.split('\n');
        const quedan = lineas.filter(l => {
          if (!_esOferta(l)) return true;
          const low = l.toLowerCase();
          if (_nombres.some(n => low.includes(n))) return true;
          if (_usado.length > 3 && low.includes(_usado)) return true;
          return false;
        });
        if (quedan.length === lineas.length) return m;
        // Encabezados de bloque que quedaron sin ningún renglón abajo ("Alto:" y nada más).
        const limpio = quedan.filter((l, i) => {
          if (!_esEncabezado(l)) return true;
          for (let k = i + 1; k < quedan.length; k++) {
            if (/^\s*$/.test(quedan[k])) continue;
            return _esItem(quedan[k]);
          }
          return false;
        });
        return Object.assign({}, m, { content: limpio.join('\n').replace(/\n{3,}/g, '\n\n').trim() });
      }).filter(m => String((m && m.content) || '').trim());
      // Si borrar dejara la respuesta vacía, no se aplica: mejor el texto de siempre que una
      // burbuja en blanco.
      if (nuevos.length) messages = nuevos;
    }
  } catch (e) {}

  // EL TEXTO TAMBIÉN, NO SÓLO LAS CARDS (v107). Si la herramienta devolvió el centinela y el texto
  // igual lista autos, esos autos están inventados por definición: no salieron de la base. La
  // respuesta se reemplaza por el guion de v102, armado acá con los mismos datos.
  // MEDIDO (ejecución 13306): el gate de v85 devolvió cero filas, v102 vació las cards, y Franco
  // listó seis autos igual —uno inexistente, "Chevrolet Cruze 2019 — $22.500.000"—. La inyección de
  // v102 estaba renderizada en ese turno y adhirió en 2 de 3 corridas: trampa 6, va a código.
  // Se reemplaza en vez de borrar renglones porque borrarlos deja colgado el encabezado
  // ("tenés este abanico estimado de opciones:" y abajo nada).
  // try/catch como todo este nodo: ante cualquier duda, el texto sale como vino.
  try {
    // LA SEÑAL QUE SÍ FUNCIONA (v111): si Franco devolvió ids y NINGUNO hidrata, esos autos no
    // están en la base — los inventó. `ids` y `autos` son main chain y son de donde salen las
    // cards. Verificado en producción: ejecución 13306 (auto_ids [111..116]) y 13702 (auto_ids
    // [197,163,128,182,148,176]); el stock va del 1 al 17. `centinela` se deja por si algún día
    // la lectura de la tool se arregla, pero hoy nunca es verdadera y por eso este bloque estaba
    // muerto desde v107.
    // SI NO PIDIÓ VER Y ESTÁ DANDO DATOS, ESTE TURNO NO ERA DE MOSTRAR (v113) — aunque los ids
    // existan y hidraten. Medido sobre v112: el turno 2 de `capacidad-de-compra-financiada` sale
    // con 5 y 6 cards de autos traídos de memoria.
    // Cada pieza es el MISMO dato que ya decide esto en otro lado, no una paráfrasis:
    // `pidio_ver` es el campo que lee el gate de `Listar stock`; el usado usa la misma expresión
    // que el fallback de TB-3 de este nodo; la plata, los mismos campos de Config que el gate de
    // v88; y `ya_derivado`, el mismo criterio que el guard de cierre de acá abajo.
    // LA GUARDA DE `ya_derivado` NO SE SACA: sin ella, en la ejecución 13797 (ya_derivado true) el
    // guion le ofrecería un asesor a alguien que YA está derivado. Ese turno queda sin tocar.
    let _noEraDeMostrar = false;
    try {
      const _le2 = $('Leer lead (estado)').first().json;
      // v115: el usado también cuenta si lo dijo EL CLIENTE en la conversación, aunque el CRM
      // todavía no lo haya escrito. Va en OR con las dos de v113 a propósito: si el regex no lo
      // caza, esto queda exactamente como estaba. `tiene_usado_hist` lo calcula el SQL de
      // `Leer lead (estado)`, del mismo modo que `ya_derivado`, y por la misma razón: el CRM
      // llega un turno tarde (ejecución 14150).
      const _tieneUsado = String(_le2.lead_entrega || '') === 'Sí' ||
        (_le2.lead_usado && _le2.lead_usado !== 'No mencionado') ||
        _le2.tiene_usado_hist === true;
      const _dioPlata = Number(cfg.monto_financiar || 0) > 0 || Number(cfg.entrega_plata || 0) > 0 ||
        Number(cfg.entrega_plata_resp || 0) > 0;
      const _yaDerivado = String(_le2.lead_estado || '') === 'Requiere asesor' || _le2.ya_derivado === true;
      _noEraDeMostrar = Number(cfg.pidio_ver || 0) === 0 && (_tieneUsado || _dioPlata) && !_yaDerivado;
    } catch (e) {}
    if (centinela || (ids.length > 0 && autos.length === 0) || _noEraDeMostrar) {
      const _le = $('Leer lead (estado)').first().json;
      const _cat = _le.catalogo_precios || [];
      const _nombres = [];
      for (const a of (Array.isArray(_cat) ? _cat : [])) {
        if (!a || !a.t) continue;
        _nombres.push(String(a.t));
        // "Volkswagen Gol Trend" -> "Gol Trend". El modelo suelto sólo cuenta si tiene letras:
        // "208" a secas matchearía dentro de cualquier monto, así que ese sólo va con la marca.
        const _mod = String(a.t).split(' ').slice(1).join(' ');
        if (/[a-z]/i.test(_mod)) _nombres.push(_mod);
      }
      let _listados = 0;
      for (const m of messages) {
        for (const l of String((m && m.content) || '').split('\n')) {
          if (!/^\s*(?:[-•*]|\d+[.)])\s+\S/.test(l)) continue;
          if (!/\$\s?\d{1,3}(?:\.\d{3})+/.test(l)) continue;
          if (_nombres.some(n => l.toLowerCase().includes(n.toLowerCase()))) _listados++;
        }
      }
      if (_listados >= 2) {
        const _usado = String(_le.lead_usado || '');
        const _conUsado = String(_le.lead_entrega || '') === 'Sí' && _usado &&
          _usado !== 'No mencionado' && _usado !== 'Auto usado mencionado, sin detalles';
        // Las cards se van con el texto (v113) — ARREGLADO DE VERDAD EN v116.
        // v113 vaciaba SÓLO `autos`, y no alcanza: `product_cards` e `images` ya se armaron
        // ~200 líneas más arriba A PARTIR de `autos`, así que vaciarlo acá no los toca y el guion
        // salía igual con las fotos abajo. MEDIDO en producción el 2026-08-10 sobre v115: el guion
        // con 6 cards (sesión 8468b31c) y con 5 (sesión 931148e9).
        // Estuvo tapado desde v113 porque el bloque casi nunca disparaba y, cuando disparaba,
        // `autos` ya venía vacío. La prueba offline de v113 asserteaba `autos.length === 0`:
        // medía la variable equivocada.
        autos.length = 0;
        product_cards = [];
        images = [];
        messages = [{ type: 'text', content: _conUsado
          ? 'Listo, ya tengo los datos de tu ' + _usado + '. La tasación final la hace un asesor viéndolo en persona. Querés que te contacte un asesor para coordinarla, o preferís que te muestre opciones que te podrían servir?'
          : 'Perfecto, ya lo tengo anotado. Querés que te contacte un asesor para avanzar, o preferís que te muestre opciones que te podrían servir?' }];
      }
    }
  } catch (e) {}

  // LAS CARDS SE RECUPERAN DEL TEXTO (v112). Si el modelo devolvió `auto_ids: []` pero el texto
  // igual ofrece autos, el cliente ve una lista sin una sola foto. Medido en
  // `stock-general-completo`: nombró los 17 autos CORRECTOS y mandó cero cards.
  // SOLO CUANDO EL CLIENTE PIDIÓ VER (`Config.pidio_ver`, el MISMO campo que lee el gate de
  // `Listar stock` — no es una réplica de la regla, es el mismo dato). Si no lo pidió, este turno
  // no era de mostrar y agregarle fotos lo empeoraría: ese caso va aparte.
  // NUNCA REESCRIBE NI BORRA NADA: sólo agrega cards de autos que el texto YA está ofreciendo, y
  // sólo si no había ninguna. Si no dispara, la respuesta es exactamente la de antes.
  // try/catch como todo este nodo: ante cualquier duda, lo de siempre.
  try {
    if (product_cards.length === 0 && images.length === 0 && Number(cfg.pidio_ver || 0) === 1) {
      const _cat = $('Leer lead (estado)').first().json.catalogo_precios || [];
      if (Array.isArray(_cat) && _cat.length) {
        const _t = messages.map(m => String((m && m.content) || '')).join('\n').toLowerCase();
        const _vistos = new Set();
        const _cards = [];
        for (const a of _cat) {
          if (!a || !a.t || !a.i || !a.f) continue;
          const _pos = _t.indexOf(String(a.t).toLowerCase());
          if (_pos < 0) continue;
          if (_vistos.has(Number(a.i))) continue;
          _vistos.add(Number(a.i));
          _cards.push({
            _pos,
            id: Number(a.i),
            titulo: String(a.t) + ' ' + String(a.a),
            precio: '$' + String(a.p).replace(/\B(?=(\d{3})+(?!\d))/g, '.'),
            foto_principal: String(a.f),
          });
        }
        // En el orden en que el cliente los lee, no en el del catálogo.
        _cards.sort((x, y) => x._pos - y._pos);
        // El mismo umbral que el camino de siempre: con menos de 3 van fotos, no cards, y las
        // fotos no se pueden reconstruir desde acá (necesitan el array `fotos` de la fila).
        // Y el mismo dedup: si TODOS ya se mandaron como card hace poco, no se repite el mazo.
        if (_cards.length >= 3 && _cards.some(c => !cardsMostradas.has(c.id))) {
          product_cards = _cards.map(c => ({
            id: c.id, titulo: c.titulo, precio: c.precio, foto_principal: c.foto_principal,
          }));
        }
      }
    }
  } catch (e) {}

  // Guard de cierre comercial: la respuesta nunca termina sin pregunta.
  let msgs = messages;
  const ultima = msgs[msgs.length - 1];
  const texto = (ultima && ultima.content) ? String(ultima.content).trim() : '';
  // El guard existe para que una LISTA DE AUTOS no quede sin pregunta de próximo paso.
  // Solo corre si este turno mostró autos: en turnos sin autos (despedida, derivación ya
  // cerrada, FAQ) pegar la pregunta genérica genera loops — le ofrecía un asesor a alguien
  // que ya lo había aceptado y dado su nombre. Medido sobre 39 turnos: de 4 disparos, los 2
  // con autos eran correctos y los 2 sin autos eran el bug.
  // Alcanza con que la última burbuja CONTENGA una pregunta: Franco a veces cierra con una
  // frase de cortesía después del "?", y con endsWith() el guard le pegaba otra encima.
  // Verificado por replay sobre 15 disparos guardados: 12 siguen disparando, y los 3 que
  // no, ya tenían pregunta propia. NO usar "alguna burbuja": el saludo tiene "?" y
  // desactivaría el guard casi siempre (se probó en v27 y se revirtió).
  if (autos.length >= 1 && !texto.includes('?')) {
    // Si el lead ya pidió que lo contacte un asesor, ofrecérselo otra vez es el bug de las
    // capturas 3-5. Se lee el estado que ya trae "Leer lead (estado)" en esta ejecución.
    // try/catch a propósito: este nodo arma la respuesta al usuario y no puede romperse
    // por el guard; ante cualquier duda, el texto de siempre.
    let yaDerivado = false;
    try { yaDerivado = $('Leer lead (estado)').first().json.lead_estado === 'Requiere asesor'; } catch (e) {}
    const cierre = product_cards.length >= 3
      ? 'Buscás algo puntual o querés que te ayude a encontrar el ideal según lo que necesitás?'
      : yaDerivado
        ? 'Cuál te llama la atención?'
        : 'Querés que un asesor te prepare una cotización, o preferís que te muestre algo parecido?';
    msgs = [...msgs, { type: 'text', content: cierre }];
  }
  // v137 · LAS URLs NO VAN EN EL TEXTO. Las fotos viajan por `images`, que es otro canal: si
  // además se escriben como texto, el cliente ve tres links kilométricos de Supabase. Medido: el
  // centinela no_url_en_texto disparó en 3 de 5 casos de una misma tanda sobre v135.
  // SI LA BURBUJA NO TIENE LINKS, EL TEXTO VUELVE INTACTO: cero efecto sobre el resto.
  const sinUrls = (t) => {
    const s = String(t || '');
    if (!/https?:\/\//.test(s)) return s;
    return s
      .replace(/https?:\/\/\S+/g, '')
      .replace(/^[\s\-–—*·]+$/gm, '')
      .replace(/[ \t]+$/gm, '')
      .replace(/\n{2,}/g, '\n')
      .trim()
      .replace(/[:\-–—,]\s*$/, '.');
  };
  msgs = msgs
    .map(m => Object.assign({}, m, {
      content: sinUrls(m.content).replace(/[¿¡]/g, ''),
    }))
    // Si la burbuja era SOLO links, queda sin nada que decir y se va (pasó: burbuja 14546 del
    // corpus, tres URLs y ni una palabra). Dejarla vacía sería peor que dejarla como estaba.
    .filter(m => /[a-zA-Z0-9áéíóúüñÁÉÍÓÚÜÑ]/.test(String(m.content || '')));

  const esPrimero = $('Contar mensajes previos').first().json.msgs_previos === 0;
  const saludo = { type: 'text', content: 'Hola! Soy ' + cfg.asistente_nombre + ', asistente de ' + cfg.empresa_nombre + '. Cómo estás?' };
  const finalMsgs = esPrimero ? [saludo, ...msgs] : msgs;
  const finalImgs = esPrimero
    ? images.map(i => Object.assign({}, i, { after_message_index: (i.after_message_index || 0) + 1 }))
    : images;

  return [{ json: {
    respuesta: { session_id: cfg.session_id, messages: finalMsgs, images: finalImgs, product_cards, error: null },
    // M2: el historial guarda EXACTAMENTE lo que vio el cliente — saludo, pregunta de
    // cierre del guard y strip de ¿/¡ incluidos. Antes guardaba `messages`/`images` crudos,
    // así que la pestaña "Historial" (la pantalla que se le muestra al dueño en la demo)
    // mostraba una conversación sin saludo, sin cierre y con los ¿ que el cliente no vio.
    // No afecta al saludo: eso lo decide "Contar mensajes previos" sobre n8n_chat_histories,
    // que es otra tabla. Tampoco al CRM, que lee n8n_chat_histories.
    historial: { messages: finalMsgs, images: finalImgs, product_cards },
  } }];
} catch (e) {
  return fallback(String(e && e.message ? e.message : e));
}

